  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `course_categories_course_name_key` (`course_name`),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_center_assignments`;
CREATE TABLE `course_center_assignments` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `center_id` INT NOT NULL,
  `allow_center_override` TINYINT(1) DEFAULT 1,
  `admin_can_customize` TINYINT(1) DEFAULT 1,
  `status` VARCHAR(30) DEFAULT 'active',
  `assigned_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `course_center_assignments_course_master_id_center_id_key` (`course_master_id`, `center_id`),
  PRIMARY KEY (id),
  CONSTRAINT `course_center_assignments_status_check` CHECK (((status)IN ('active', 'inactive', 'pending')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_center_fees`;
CREATE TABLE `course_center_fees` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `center_id` INT NOT NULL,
  `total_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `offer_amount` DECIMAL(12,2),
  `discount_amount` DECIMAL(12,2) DEFAULT 0,
  `registration_fee` DECIMAL(12,2) DEFAULT 0,
  `num_installments` INT DEFAULT 1,
  `installment_1_amount` DECIMAL(12,2),
  `installment_2_amount` DECIMAL(12,2),
  `installment_3_amount` DECIMAL(12,2),
  `installment_due_rules` JSON DEFAULT ('[]'),
  `additional_discounts` JSON DEFAULT ('[]'),
  `configured_by` VARCHAR(20) DEFAULT 'center',
  `status` VARCHAR(30) DEFAULT 'draft',
  `saved_at` DATETIME,
  `approved_at` DATETIME,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `course_center_fees_configured_by_check` CHECK (((configured_by)IN ('admin', 'center'))),
  UNIQUE KEY `course_center_fees_course_master_id_center_id_key` (`course_master_id`, `center_id`),
  PRIMARY KEY (id),
  CONSTRAINT `course_center_fees_status_check` CHECK (((status)IN ('draft', 'saved', 'approved', 'rejected')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_fee_discounts`;
CREATE TABLE `course_fee_discounts` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `center_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `discount_type` VARCHAR(20) NOT NULL,
  `discount_value` DECIMAL(12,2) NOT NULL,
  `coupon_code` VARCHAR(100),
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `course_fee_discounts_discount_type_check` CHECK (((discount_type)IN ('percent', 'fixed'))),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_master_batches`;
CREATE TABLE `course_master_batches` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `batch_name` VARCHAR(255),
  `start_date` DATE NOT NULL,
  `end_date` DATE,
  `is_active` TINYINT(1) DEFAULT 1,
  `display_order` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `batch_timing` VARCHAR(255),
  `schedule_days` VARCHAR(255),
  `capacity` INT,
  `enrollment_deadline` DATE,
  `notes` TEXT,
  `price` DECIMAL(12,2),
  `discount_percent` DECIMAL(5,2),
  `discount_amount` DECIMAL(12,2),
  `coupon_code` VARCHAR(100),
  `coupon_enabled` TINYINT(1) DEFAULT 0,
  `installment_config` JSON DEFAULT ('[]'),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_master_faculty`;
CREATE TABLE `course_master_faculty` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `role` VARCHAR(255),
  `bio` TEXT,
  `image_url` TEXT,
  `display_order` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_master_faqs`;
CREATE TABLE `course_master_faqs` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `course_master_id` INT NOT NULL,
  `question` TEXT NOT NULL,
  `answer` TEXT NOT NULL,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_masters`;
CREATE TABLE `course_masters` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `parent_id` INT,
  `level_type` VARCHAR(30) NOT NULL,
  `title` VARCHAR(500) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `short_description` TEXT,
  `detailed_description` TEXT,
  `image_url` TEXT,
  `brochure_url` TEXT,
  `syllabus_html` TEXT,
  `syllabus_pdf_url` TEXT,
  `demo_class_link` TEXT,
  `highlights` JSON DEFAULT ('[]'),
  `features` JSON DEFAULT ('[]'),
  `learning_outcomes` JSON DEFAULT ('[]'),
  `eligibility_criteria` JSON DEFAULT ('[]'),
  `duration` VARCHAR(100),
  `mode` VARCHAR(20),
  `price` DECIMAL(12,2),
  `discount_percent` DECIMAL(5,2),
  `discount_amount` DECIMAL(12,2),
  `coupon_code` VARCHAR(100),
  `coupon_enabled` TINYINT(1) DEFAULT 0,
  `installment_config` JSON DEFAULT ('[]'),
  `enrollment_validity_days` INT,
  `meta_title` VARCHAR(255),
  `meta_description` TEXT,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `course_masters_level_type_check` CHECK (((level_type)IN ('main_course', 'sub_variant', 'course', 'sub_sub_variant', 'leaf_course'))),
  CONSTRAINT `course_masters_mode_check` CHECK (((mode IS NULL) OR ((mode)IN ('online', 'offline', 'hybrid')))),
  PRIMARY KEY (id),
  UNIQUE KEY `course_masters_slug_key` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `category` VARCHAR(100),
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `icon_class` VARCHAR(100) DEFAULT 'ri-book-open-line',
  `description` TEXT,
  `thumbnail_url` TEXT,
  `badge_label` VARCHAR(255),
  `promo_line_1` VARCHAR(500),
  `promo_line_2` VARCHAR(500),
  `original_price` VARCHAR(64),
  `discounted_price` VARCHAR(64),
  `offer_text` TEXT,
  `enroll_url` TEXT,
  `course_category_id` INT,
  `category_slug` VARCHAR(255),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cta_sliders`;
CREATE TABLE `cta_sliders` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `text` VARCHAR(255) NOT NULL,
  `link_url` VARCHAR(255),
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_sections`;
CREATE TABLE `custom_sections` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `section_type` VARCHAR(50) NOT NULL,
  `title` VARCHAR(255),
  `content` TEXT,
  `config` JSON,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `email_templates`;
CREATE TABLE `email_templates` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `template_key` VARCHAR(100) NOT NULL,
  `template_name` VARCHAR(255) NOT NULL,
  `template_category` VARCHAR(50) DEFAULT 'general',
  `subject` VARCHAR(255) NOT NULL,
  `html_content` TEXT NOT NULL,
  `text_content` TEXT,
  `description` TEXT,
  `variables` JSON,
  `is_active` TINYINT(1) DEFAULT 1,
  `is_system_template` TINYINT(1) DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY `email_templates_template_key_key` (`template_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `employees`;
CREATE TABLE `employees` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT NOT NULL,
  `employee_code` VARCHAR(50),
  `full_name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255),
  `mobile` VARCHAR(50),
  `alternate_mobile` VARCHAR(50),
  `job_title` VARCHAR(150),
  `department` VARCHAR(150),
  `employment_type` VARCHAR(50) NOT NULL DEFAULT 'full_time',
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  `join_date` DATE,
  `end_date` DATE,
  `date_of_birth` DATE,
  `gender` VARCHAR(20),
  `address` TEXT,
  `city` VARCHAR(100),
  `state` VARCHAR(100),
  `pincode` VARCHAR(20),
  `emergency_contact_name` VARCHAR(255),
  `emergency_contact_phone` VARCHAR(50),
  `admin_user_id` INT,
  `documents` JSON NOT NULL DEFAULT ('[]'),
  `notes` TEXT,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `employees_employment_type_check` CHECK (((employment_type)IN ('full_time', 'part_time', 'contract', 'intern', 'consultant'))),
  PRIMARY KEY (id),
  CONSTRAINT `employees_status_check` CHECK (((status)IN ('active', 'inactive', 'on_leave', 'terminated')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `expenses`;
CREATE TABLE `expenses` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT NOT NULL,
  `employee_id` INT NOT NULL,
  `category` VARCHAR(50) NOT NULL,
  `amount` DECIMAL(12,2) NOT NULL,
  `expense_date` DATE NOT NULL,
  `description` TEXT,
  `receipt_url` TEXT,
  `receipt_name` VARCHAR(255),
  `payment_method` VARCHAR(50) NOT NULL DEFAULT 'cash',
  `status` VARCHAR(30) NOT NULL DEFAULT 'draft',
  `approval_notes` TEXT,
  `notes` TEXT,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `expenses_amount_check` CHECK ((amount > (0))),
  CONSTRAINT `expenses_category_check` CHECK (((category)IN ('travel', 'food', 'office_supplies', 'utilities', 'rent', 'salary', 'marketing', 'maintenance', 'training', 'transport', 'communication', 'miscellaneous'))),
  CONSTRAINT `expenses_payment_method_check` CHECK (((payment_method)IN ('cash', 'upi', 'bank_transfer', 'cheque', 'card', 'other'))),
  PRIMARY KEY (id),
  CONSTRAINT `expenses_status_check` CHECK (((status)IN ('draft', 'pending', 'approved', 'rejected', 'paid')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `faqs`;
CREATE TABLE `faqs` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `question` TEXT NOT NULL,
  `answer` TEXT NOT NULL,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `footer_menu_items`;
CREATE TABLE `footer_menu_items` (
  `id` INT NOT NULL AUTO_INCREMENT,
