  `title` VARCHAR(255) NOT NULL,
  `icon_class` VARCHAR(100),
  `link_url` VARCHAR(255),
  `target_section` VARCHAR(100),
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `gallery_images`;
CREATE TABLE `gallery_images` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `title` VARCHAR(255) NOT NULL,
  `image_url` TEXT NOT NULL,
  `gallery_type` VARCHAR(50) DEFAULT 'general',
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `global_settings`;
CREATE TABLE `global_settings` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `setting_key` VARCHAR(100) NOT NULL,
  `setting_value` TEXT,
  `setting_type` VARCHAR(50) DEFAULT 'string',
  `description` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY `global_settings_setting_key_key` (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `header_menu_items`;
CREATE TABLE `header_menu_items` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `menu_key` VARCHAR(100) NOT NULL,
  `parent_id` INT,
  `title` VARCHAR(255) NOT NULL,
  `icon_class` VARCHAR(100),
  `link_url` VARCHAR(255),
  `target_section` VARCHAR(100),
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `hero_slides`;
CREATE TABLE `hero_slides` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `title` VARCHAR(255) NOT NULL,
  `subtitle` VARCHAR(255),
  `description` TEXT,
  `button_text` VARCHAR(100),
  `button_link` VARCHAR(255),
  `video_link` VARCHAR(255),
  `background_image_url` TEXT,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `slider_image_url` TEXT,
  `show_content` TINYINT(1) DEFAULT 1,
  `approval_status` VARCHAR(20) DEFAULT 'pending',
  `approved_by` INT,
  `approved_at` DATETIME,
  `rejection_reason` TEXT,
  CONSTRAINT `hero_slides_approval_status_check` CHECK (((approval_status)IN ('pending', 'approved', 'rejected'))),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `image_library`;
CREATE TABLE `image_library` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `filename` VARCHAR(255) NOT NULL,
  `original_filename` VARCHAR(255),
