  `file_url` TEXT NOT NULL,
  `file_size` INT,
  `mime_type` VARCHAR(100),
  `width` INT,
  `height` INT,
  `alt_text` VARCHAR(255),
  `tags` JSON,
  `uploaded_by_user_type` VARCHAR(50),
  `uploaded_by_user_id` INT,
  `usage_count` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `leadership`;
CREATE TABLE `leadership` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `role` VARCHAR(255) NOT NULL,
  `image_url` TEXT,
  `message_title` VARCHAR(255),
  `message_content` TEXT,
  `bio` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `nearby_centers`;
CREATE TABLE `nearby_centers` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `nearby_center_id` INT,
  `display_order` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `nearby_centers_center_id_nearby_center_id_key` (`center_id`, `nearby_center_id`),
  CONSTRAINT `nearby_centers_check` CHECK ((center_id <> nearby_center_id)),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `news_items`;
CREATE TABLE `news_items` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` INT,
  `title` VARCHAR(255) NOT NULL,
  `content` TEXT,
  `link_url` VARCHAR(255),
  `is_new` TINYINT(1) DEFAULT 0,
  `is_notification` TINYINT(1) DEFAULT 0,
  `display_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `approval_status` VARCHAR(20) DEFAULT 'pending',
  `approved_by` INT,
  `approved_at` DATETIME,
  `rejection_reason` TEXT,
  CONSTRAINT `news_items_approval_status_check` CHECK (((approval_status)IN ('pending', 'approved', 'rejected'))),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_type` VARCHAR(50) NOT NULL,
  `user_id` INT NOT NULL,
  `center_id` INT,
  `title` VARCHAR(255) NOT NULL,
  `message` TEXT NOT NULL,
  `type` VARCHAR(50) DEFAULT 'info',
  `link_url` VARCHAR(500),
  `is_read` TINYINT(1) DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_type` VARCHAR(50) NOT NULL,
  `user_id` INT NOT NULL,
  `token` VARCHAR(255) NOT NULL,
  `expires_at` DATETIME NOT NULL,
  `used` TINYINT(1) DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY `password_reset_tokens_token_key` (`token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payment_receipt_sequences`;
CREATE TABLE `payment_receipt_sequences` (
  `center_id` INT NOT NULL,
  `year` INT NOT NULL,
  `last_seq` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (center_id, year)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL,
  `resource` VARCHAR(100) NOT NULL,
  `action` VARCHAR(50) NOT NULL,
  `description` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `permissions_name_key` (`name`),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `rate_limit_buckets`;
CREATE TABLE `rate_limit_buckets` (
