DROP TABLE IF EXISTS `student_fee_payments`;
CREATE TABLE `student_fee_payments` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `receipt_no` VARCHAR(50) NOT NULL,
  `center_id` INT NOT NULL,
  `course_master_id` INT NOT NULL,
  `student_name` VARCHAR(255) NOT NULL,
  `student_email` VARCHAR(255),
  `student_mobile` VARCHAR(50) NOT NULL,
  `payment_type` VARCHAR(30) DEFAULT 'lumpsum',
  `installment_no` INT,
  `fee_snapshot` JSON NOT NULL DEFAULT ('{}'),
  `amount_due` DECIMAL(12,2) NOT NULL,
  `amount_paid` DECIMAL(12,2) NOT NULL,
  `discount_applied` DECIMAL(12,2) DEFAULT 0,
  `payment_method` VARCHAR(50),
  `transaction_id` VARCHAR(255),
  `status` VARCHAR(30) DEFAULT 'completed',
  `notes` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `batch_id` INT,
  `idempotency_key` VARCHAR(100),
  `gateway_order_id` VARCHAR(100),
  `coupon_code` VARCHAR(100),
  `discount_id` INT,
  `gst_amount` DECIMAL(12,2) DEFAULT 0,
  `gst_rate` DECIMAL(5,2) DEFAULT 18,
  `created_by` VARCHAR(255),
  `client_ip` VARCHAR(45),
  `gateway_response` JSON DEFAULT ('{}'),
  `refunded_at` DATETIME,
  `refund_transaction_id` VARCHAR(255),
  `student_id` INT,
  CONSTRAINT `student_fee_payments_payment_type_check` CHECK (((payment_type)IN ('lumpsum', 'installment'))),
  PRIMARY KEY (id),
  UNIQUE KEY `student_fee_payments_receipt_no_key` (`receipt_no`),
  CONSTRAINT `student_fee_payments_status_check` CHECK (((status)IN ('pending', 'completed', 'failed', 'refunded')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

